    const sr = X.uioRows('ser', rg); if (sr) out.push(TB([{ h: 'Baureihe', w: 1.7 }, { h: 'UIO Tsd.', w: 0.9, a: 'r' }, { h: 'Umsatz/UIO', w: 1.1, a: 'r' }, { h: 'Neufz./UIO', w: 1.1, a: 'r' }, { h: 'Rekl./UIO', w: 1.1, a: 'r' }, { h: 'Garantie/UIO', w: 1.2, a: 'r' }], sr.rows.map((q) => [q.name, N1.format(q.uio), N1.format(q.revv) + ' k€', N1.format(q.newv), N2.format(q.clmv), N2.format(q.costv) + ' k€'])));
